public class BSTSearch { static class Node{String k;Node l,r;Node(String k){this.k=k;}} static Node insert(Node n,String k){if(n==null)return new Node(k);if(k.compareToIgnoreCase(n.k)<0)n.l=insert(n.l,k);else if(k.compareToIgnoreCase(n.k)>0)n.r=insert(n.r,k);return n;} static boolean search(Node n,String k){while(n!=null){int c=k.compareToIgnoreCase(n.k);if(c==0)return true;n=c<0?n.l:n.r;}return false;} }